/// Model-defined explanation payload. Uses the same format-discriminator pattern as table payloads: a required `format` field plus other fields depending on the format. The set of formats is open and model-defined (e.g. `natural_language_summary`, `feature_attributions`, `subgraph`), so a client branches on `format` to interpret the contents. A model advertises the format(s) it emits via its capability `explanation_formats`. Prediction scores are not duplicated here; they remain in `prediction` / `probabilities`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Explanation {
    /// Discriminator naming the explanation shape this model emits.
    pub format: String,
    /// Keys the contract does not name, kept as they came.
    #[serde(flatten)]
    pub additional_properties: Map<String, Value>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RankingItem {
    pub id: String,
    pub score: Number,
}

